{
  "rule": "When the facts describe the illegal manufacturing and/or trading of police uniforms, caps, or other police gear, the charge must be the specific statutory offense '非法生产、买卖警用装备' rather than a generic term like '非法买卖警用物品'.",
  "keywords": [
    "非法买卖警服",
    "警便帽",
    "训练服",
    "警用装备",
    "生产并买卖警用装备"
  ]
}
